content:
:root {
  font-family: Inter, system-ui, Avenir, Helvetica, Arial, sans-serif;
  line-height: 1.5;
  font-weight: 400;

  color-scheme: light dark;
  color: rgba(255, 255, 255, 0.87);
  background-color: #242424;

  font-synthesis: none;
  text-rendering: optimizeLegibility;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  margin: 0;
  display: flex;
  place-items: center;
  min-width: 320px;
  min-height: 100vh;
  justify-content: center;
  background: linear-gradient(135deg, #1e1e2f 0%, #2a2a40 100%);
}

* {
  box-sizing: border-box;
}

.todo-container {
  width: 100%;
  max-width: 480px;
  margin: 0 auto;
  padding: 2rem;
  background: #1e1e2f;
  border-radius: 16px;
  box-shadow: 0 10px 25px rgba(0, 0, 0, 0.3);
  border: 1px solid rgba(255, 255, 255, 0.1);
}

.todo-header {
  font-size: 1.8rem;
  font-weight: 700;
  margin-bottom: 1.5rem;
  text-align: center;
  color: #fff;
  letter-spacing: -0.025em;
}

.todo-input-form {
  display: flex;
  gap: 0.5rem;
  margin-bottom: 1.5rem;
}

.todo-input {
  flex: 1;
  padding: 0.75rem 1rem;
  font-size: 1rem;
  border-radius: 8px;
  border: 1px solid #3f3f5f;
  background-color: #2a2a40;
  color: #fff;
  outline: none;
  transition: border-color 0.2s, box-shadow 0.2s;
}

.todo-input:focus {
  border-color: #6366f1;
  box-shadow: 0 0 0 2px rgba(99, 102, 241, 0.2);
}

.todo-btn {
  padding: 0.75rem 1.25rem;
  font-size: 1rem;
  font-weight: 600;
  border: none;
  border-radius: 8px;
  background-color: #6366f1;
  color: white;
  cursor: pointer;
  transition: background-color 0.2s, transform 0.1s;
}

.todo-btn:hover {
  background-color: #4f46e5;
}

.todo-btn:active {
  transform: scale(0.98);
}

.todo-list {
  list-style: none;
  padding: 0;
  margin: 0;
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
  max-height: 400px;
  overflow-y: auto;
}

.todo-item {
  display: flex;
  align-items: center;
  padding: 0.75rem 1rem;
  background-color: #2a2a40;
  border-radius: 8px;
  border: 1px solid #3f3f5f;
  transition: background-color 0.2s, border-color 0.2s;
}

.todo-item:hover {
  border-color: #52527a;
}

.todo-checkbox {
  width: 1.25rem;
  height: 1.25rem;
  cursor: pointer;
  accent-color: #6366f1;
  margin-right: 0.75rem;
}

.todo-text {
  flex: 1;
  font-size: 1rem;
  color: #e2e8f0;
  word-break: break-all;
  transition: color 0.2s, text-decoration 0.2s;
}

.todo-item:has(.todo-checkbox:checked) .todo-text {
  color: #94a3b8;
  text-decoration: line-through;
}

.todo-delete-btn {
  background: transparent;
  border: none;
  color: #ef4444;
  cursor: pointer;
  font-size: 1.25rem;
  padding: 0.25rem 0.5rem;
  border-radius: 4px;
  transition: background-color 0.2s, color 0.2s;
}

.todo-delete-btn:hover {
  background-color: rgba(239, 68, 68, 0.1);
  color: #dc2626;
}

.todo-empty {
  text-align: center;
  color: #94a3b8;
  padding: 2rem 0;
  font-size: 0.95rem;
}

@media (max-width: 480px) {
  .todo-container {
    padding: 1rem;
    border-radius: 0;
    height: 100vh;
    max-width: 100%;
    border: none;
    display: flex;
    flex-direction: column;
  }

  .todo-list {
    flex: 1;
    max-height: none;
  }
}

export interface Task {
  id: string;
  text: string;
  completed: boolean;
}

import { useState, FormEvent } from 'react';
import { Task } from './types';
import './index.css';

export default function App() {
  const [tasks, setTasks] = useState<Task[]>([
    { id: '1', text: 'Reactのプロジェクトを作成する', completed: true },
    { id: '2', text: 'やることリストの機能を実装する', completed: false },
    { id: '3', text: '動作確認を行う', completed: false }
  ]);
  const [inputText, setInputText] = useState('');

  const handleAddTask = (e: FormEvent) => {
    e.preventDefault();
    if (!inputText.trim()) return;

    const newTask: Task = {
      id: Date.now().toString(),
      text: inputText.trim(),
      completed: false,
    };

    setTasks([...tasks, newTask]);
    setInputText('');
  };

  const handleToggleTask = (id: string) => {
    setTasks(
      tasks.map((task) =>
        task.id === id ? { ...task, completed: !task.completed } : task
      )
    );
  };

  const handleDeleteTask = (id: string) => {
    setTasks(tasks.filter((task) => task.id !== id));
  };

  return (
    <div className="todo-container">
      <h1 className="todo-header">やることリスト</h1>

      <form className="todo-input-form" onSubmit={handleAddTask}>
        <input
          type="text"
          className="todo-input"
          placeholder="新しいタスクを入力..."
          value={inputText}
          onChange={(e) => setInputText(e.target.value)}
        />
        <button type="submit" className="todo-btn">追加</button>
      </form>

      {tasks.length === 0 ? (
        <div className="todo-empty">タスクはまだありません。新しいタスクを追加してください！</div>
      ) : (
        <ul className="todo-list">
          {tasks.map((task) => (
            <li key={task.id} className="todo-item">
              <input
                type="checkbox"
                className="todo-checkbox"
                checked={task.completed}
                onChange={() => handleToggleTask(task.id)}
              />
              <span className="todo-text">{task.text}</span>
              <button
                type="button"
                className="todo-delete-btn"
                onClick={() => handleDeleteTask(task.id)}
                aria-label="削除"
              >
                ×
              </button>
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}
